with unpacked as (select id, service, host, status_code, payload_json, context, size(context) as num_context, coalesce(context['version'], 'direct') as version_or_default from app_logs) select *, max(status_code) over w_hist as last4_max_status_code, count(status_code) over w_hist as last4_count_status_code, sum(status_code) over w_hist as last4_sum_status_code from unpacked window w_hist as (partition by host order by status_code, id rows between 3 preceding and current row);
